declare(strict_types=1);
$root=dirname(__DIR__);$baseline=json_decode(file_get_contents($root.'/Docs/estabilizacao-v04/baseline.json'),true,512,JSON_THROW_ON_ERROR);
$allowed=['app/Game.php'=>'Resolução unificada de execução e rastreio; RNG do teste.','app/Probability.php'=>'RNG injetável validado; random_int continua padrão.','app/PlayMode.php'=>'Audita componentes de chance sem alterar seleção.'];$allowed+=['app/Wheel.php'=>'SVG de círculo completo para mercado sem candidatos, fatia única.','app/MatchMomentum.php'=>'Posse testemunhada e encerramento por interrupção.','app/Competition.php'=>'Continuidade Amazonense e bloqueio de acessos órfãos.','app/ClubSquad.php'=>'Fallback explícito dos quatro clubes indispensáveis no jogo.','app/CompetitionView.php'=>'Aviso de teto simulado, sem promoção fictícia.','app/TransferMarket.php'=>'Avaliação e cenários de interesse aprovados v0.4.','app/Presentation.php'=>'Labels públicos e antes/depois do perfil.','app/view.php'=>'Impactos da roleta antes do giro.','app/Repository.php'=>'Persistência aditiva e medição opt-in de consultas/engine/save.','public/index.php'=>'Índice explícito da oferta escolhida.','public/assets/game.js'=>'Loader, erro, timeout e envio único.','public/assets/game.css'=>'Painel acessível de espera e impactos.'];$rows=[];
foreach($baseline['hashes'] as $file=>$hash){$same=hash_equals($hash,hash('sha256',str_replace("\r\n","\n",file_get_contents($root.'/'.$file))));if(!$same&&!isset($allowed[$file]))throw new RuntimeException('Fora da superfície mecânica autorizada: '.$file);$rows[]=['file'=>$file,'unchanged'=>$same,'intentional_reason'=>$same?null:$allowed[$file]];}
file_put_contents($root.'/Docs/estabilizacao-v04/fronteiras.json',json_encode($rows,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));echo 'OK: '.count($rows)." arquivos comparados; catálogo, gates, pesos, sementes, snapshots e demais mecânicas preservados.\n";
